window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[128]={"id":"128","numero":128,"titre":"Ostéopathies fragilisantes","objectifs":[{"id":"128-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’ostéoporose (densitométrique et fractures)","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> L'<span class=\"kw-def\">ostéoporose</span> est une <span class=\"kw-def\">maladie généralisée et diffuse du squelette</span> caractérisée par une <span class=\"kw-def\">résistance osseuse diminuée</span> (fragilité osseuse) prédisposant à un risque élevé de <span class=\"kw-alerte\">fracture</span>. La résistance osseuse résulte de deux composantes :</div>\n      <ul>\n        <li><strong>Densité osseuse</strong> — diminution du <span class=\"kw-def\">contenu minéral osseux</span></li>\n        <li><strong>Qualité osseuse</strong> — altération de la <span class=\"kw-def\">microarchitecture osseuse</span> notamment</li>\n      </ul>\n\n      <p><strong>Définition densitométrique</strong> — c'est le <span class=\"kw-bio\">T-score</span> à l'<span class=\"kw-imagerie\">ostéodensitométrie (DXA)</span> qui définit l'ostéoporose densitométrique :</p>\n      <table >\n        <thead><tr><th>Catégorie densitométrique</th><th>T-<span class=\"kw-def\">score</span> (au col fémoral)</th></tr></thead>\n        <tbody>\n          <tr><td>DMO normale</td><td><span class=\"kw-chiffre\">T-score &gt; − 1</span></td></tr>\n          <tr><td>Ostéopénie (densité intermédiaire)</td><td><span class=\"kw-chiffre\">− 2,5 &lt; T-score ≤ − 1</span></td></tr>\n          <tr><td><strong>Ostéoporose densitométrique</strong></td><td><span class=\"kw-chiffre\">T-score ≤ − 2,5</span></td></tr>\n          <tr><td>Ostéoporose sévère / confirmée</td><td>T-<span class=\"kw-def\">score</span> ≤ − 2,5 <strong>+</strong> <span class=\"kw-alerte\">≥ 1 fracture ostéoporotique</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Limite de la définition densitométrique.</strong> La <span class=\"kw-bio\">moitié des fractures</span> ostéoporotiques surviennent chez des patients avec une <span class=\"kw-chiffre\">DMO &gt; − 2,5</span>, et tous <span class=\"kw-clinique\">les</span> patients avec une DMO &lt; − 2,5 ne feront pas de fracture. La DMO est donc à considérer avant tout comme un <strong><span class=\"kw-def\">facteur de risque</span> majeur</strong> de fracture, pas comme une condition nécessaire et suffisante.</div>\n\n      <p><strong>Place de la fracture.</strong> L'<span class=\"kw-alerte\">épisode fracturaire</span> est la <strong>complication</strong> de la maladie ostéoporotique et en constitue toute la gravité. On distingue deux grands mécanismes étiologiques :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Ostéoporose primitive</span> — commune, dite <strong>post-ménopausique</strong> (secondaire au déficit œstrogénique chez la femme)</li>\n        <li><span class=\"kw-etio\">Ostéoporose secondaire</span> — induite par d'autres pathologies ou des traitements ; plus fréquente chez l'homme (<span class=\"kw-chiffre\">&gt; 50 %</span> des cas masculins)</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 363 — Fractures fréquentes de l'adulte et du sujet âgé</em></p>","frequence":5},{"id":"128-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie des fractures ostéoporotiques","contenu":"<div class=\"callout callout-info\"><strong>Une maladie fréquente et silencieuse.</strong> L'ostéoporose densitométrique touche <span class=\"kw-chiffre\">40 %</span> des sujets à <span class=\"kw-chiffre\">65 ans</span> et <span class=\"kw-chiffre\">70 %</span> à <span class=\"kw-chiffre\">80 ans</span> ; elle reste asymptomatique jusqu'à l'événement fracturaire.</div>\n\n      <ul>\n        <li><strong>Fractures par fragilité (France, 2019)</strong> : <span class=\"kw-chiffre\">≈ 480 000</span> nouvelles fractures/an, estimées à <span class=\"kw-chiffre\">610 000 en 2034</span> avec le vieillissement de la population</li>\n        <li><strong><span class=\"kw-def\">Prévalence</span> des fractures à<span class=\"kw-chiffre\"> 50 ans</span></strong> : <span class=\"kw-chiffre\">50 % des femmes</span> et <span class=\"kw-chiffre\">20 % des hommes</span> feront une fracture ostéoporotique au cours de leur vie</li>\n      </ul>\n\n      <p><strong><span class=\"kw-def\">Incidence</span> par ordre de fréquence décroissant</strong> :</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Incidence annuelle</th><th>Particularité</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fractures vertébrales</strong></td><td><span class=\"kw-chiffre\">50 000 – 75 000</span></td><td>Répartition <span class=\"kw-clinique\">égale</span> dans <span class=\"kw-clinique\">les</span> deux sexes</td></tr>\n          <tr><td><strong>FESF</strong> (extrémité supérieure du fémur)</td><td><span class=\"kw-chiffre\">50 000 – 60 000</span></td><td><span class=\"kw-chiffre\">25–30 %</span> surviennent chez l'homme ; excès de <span class=\"kw-def\">mortalité</span></td></tr>\n          <tr><td><strong>Poignet</strong> (Pouteau-Colles)</td><td><span class=\"kw-chiffre\">≈ 35 000</span></td><td>Beaucoup plus rare chez l'homme ; fracture la plus <span class=\"kw-clinique\">précoce</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 363 — Fractures fréquentes de l'adulte et du sujet âgé · 131 — Troubles de la marche et de l'équilibre du sujet âgé</em></p>","frequence":3},{"id":"128-3","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître la physiopathologie de l’ostéoporose primitive","contenu":"<p><strong>Remodelage osseux.</strong> Le tissu osseux est remanié en permanence (plus rapide dans l'<span class=\"kw-def\">os trabéculaire</span> que cortical) par un couplage de deux phases :</p>\n      <ul>\n        <li>Phase de <span class=\"kw-def\">résorption</span> — assurée par <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">ostéoclastes</span> (cellules multinucléées)</li>\n        <li>Phase de <span class=\"kw-def\">formation</span> — assurée par <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">ostéoblastes</span>, qui forment le tissu ostéoïde se minéralisant sous l'action de la <span class=\"kw-bio\">vitamine D</span> et du <span class=\"kw-bio\">calcium</span></li>\n      </ul>\n\n      <p><strong>Capital osseux au cours de la vie.</strong></p>\n      <table >\n        <thead><tr><th>Étape</th><th>Bilan résorption / formation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Pic de <span class=\"kw-clinique\">masse</span> osseuse</strong> (<span class=\"kw-chiffre\">20–30 ans</span>)</td><td>Formation &gt; résorption. Déterminants : <span class=\"kw-etio\">génétique</span> (<span class=\"kw-chiffre\">60–80 %</span>), <span class=\"kw-etio\">puberté</span>, <span class=\"kw-etio\">activité physique</span>, apports <span class=\"kw-etio\">calciques</span> et <span class=\"kw-etio\">protéiques</span>, <span class=\"kw-etio\">toxiques</span> (<span class=\"kw-etio\">alcool</span>, tabac, médicaments)</td></tr>\n          <tr><td>Plateau</td><td><span class=\"kw-clinique\">Masse</span> osseuse stable ≈<span class=\"kw-chiffre\"> 15 ans</span></td></tr>\n          <tr><td><strong>Femme — ménopause</strong></td><td><span class=\"kw-clinique\">Accélération</span> de la perte (jusqu'à <span class=\"kw-chiffre\">2–3 %/an</span> au rachis pendant <span class=\"kw-chiffre\">3–5 ans</span>), prédominant sur l'<span class=\"kw-def\">os trabéculaire</span> (carence œstrogénique)</td></tr>\n          <tr><td>Homme</td><td>Perte osseuse <span class=\"kw-clinique\">linéaire</span> liée au vieillissement</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Deux mécanismes de l'ostéoporose primitive.</strong>\n        <ul>\n          <li><strong>Acquisition d'un pic de <span class=\"kw-clinique\">masse</span> osseuse faible</strong> au cours de la croissance</li>\n          <li><strong>Perte osseuse accrue</strong> à l'âge adulte, par augmentation de la <span class=\"kw-def\">résorption</span> (ex. <span class=\"kw-etio\">ménopause</span>) ou diminution de la <span class=\"kw-def\">formation</span> (ex. <span class=\"kw-etio\">corticothérapie</span>)</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 124 — Ménopause - andropause</em></p>","frequence":1},{"id":"128-4","rang":"A","rubrique":"Etiologies","titre":"Connaître les causes d’ostéoporose primitive et secondaire","contenu":"<div class=\"callout callout-danger\"><strong>⭐ Objectif très tombable.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">facteurs de risque</span> d'ostéoporose primitive et les <span class=\"kw-etio\">causes secondaires</span> sont un grand classique des annales. Penser à chercher une cause secondaire <strong>tout particulièrement chez l'homme</strong> (&gt;<span class=\"kw-chiffre\"> 50 %</span> des cas).</div>\n\n      <p><strong>1 · Ostéoporose primitive — <span class=\"kw-def\">facteurs de risque</span></strong></p>\n      <table >\n        <thead><tr><th>FR dépendant de la DMO</th><th>FR (partiellement) indépendant de la DMO</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li>Origine <span class=\"kw-etio\">caucasienne</span> ou <span class=\"kw-etio\">asiatique</span></li>\n                <li><span class=\"kw-etio\">Carence œstrogénique</span> : ménopause (surtout précoce <span class=\"kw-chiffre\">&lt; 40 ans</span>), nulliparité, aménorrhée</li>\n                <li>Diminution de la sécrétion <span class=\"kw-etio\">androgénique</span></li>\n                <li>Faible apport <span class=\"kw-etio\">calcique</span>, carence en <span class=\"kw-bio\">vitamine D</span> (hyperparathyroïdie secondaire)</li>\n                <li>Consommation excessive d'<span class=\"kw-etio\">alcool</span></li>\n                <li><span class=\"kw-etio\">Endocrinopathies</span> : hyperparathyroïdie, hyperthyroïdie, <span class=\"kw-etio\">diabète</span>, Cushing, hypogonadisme</li>\n                <li>Maladies <span class=\"kw-etio\">inflammatoires</span> : <span class=\"kw-clinique\">PR</span>, BPCO</li>\n                <li>Maladie de <span class=\"kw-etio\">Parkinson</span>, carence <span class=\"kw-etio\">protéique</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Âge <span class=\"kw-chiffre\">&gt; 60 ans</span> (lié au risque de chute, surtout FESF)</li>\n                <li><span class=\"kw-clinique\">ATCD familial</span> de fracture par fragilité (parent 1er degré)</li>\n                <li><span class=\"kw-clinique\">ATCD personnel</span> de fracture ostéoporotique (++ si récente)</li>\n                <li><span class=\"kw-alerte\">Chute</span> ou risque de chute</li>\n                <li>Faible poids — <span class=\"kw-chiffre\">IMC &lt; 19</span></li>\n                <li>Troubles de l'acuité <span class=\"kw-clinique\">visuelle</span>, troubles neuromusculaires</li>\n                <li><span class=\"kw-etio\">Immobilisation</span> prolongée, <span class=\"kw-etio\">tabagisme</span></li>\n                <li><span class=\"kw-ttt\">Corticothérapie</span> (&gt; <span class=\"kw-chiffre\">7,5 mg/j</span> pendant &gt; <span class=\"kw-chiffre\">3 mois</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p style=\"margin-top:18px\"><strong>2 · Ostéoporoses secondaires — endocriniennes</strong> (principales causes secondaires)</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Mécanisme osseux</th><th>Os touché</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Hypogonadisme</span></td><td>Diminution des stéroïdes sexuels (<span class=\"kw-clinique\">anorexie</span>, hyperprolactinémie, agonistes GnRH, anti-aromatases, Turner)</td><td>Os <span class=\"kw-def\">trabéculaire</span></td></tr>\n          <tr><td>Syndrome de <span class=\"kw-etio\">Cushing</span> / <span class=\"kw-ttt\">corticoïdes</span></td><td>↓ formation + ↑ résorption ; ↓ absorption et ↑ fuite urinaire du Ca → <span class=\"kw-bio\">hyperparathyroïdie secondaire</span>. Atteinte <strong>dès la 1ʳᵉ année</strong></td><td>Os <span class=\"kw-def\">trabéculaire</span> (vertèbres, côtes)</td></tr>\n          <tr><td><span class=\"kw-etio\">Hyperthyroïdie</span> / hormones thyroïdiennes freinatrices</td><td>↑ remodelage en défaveur de la formation</td><td>Os <span class=\"kw-def\">cortical</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Hyperparathyroïdie</span>, <span class=\"kw-etio\">hémochromatose</span></td><td>↑ résorption</td><td>Os cortical</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>⚠️ Piège annale.</strong> Le <span class=\"kw-etio\">diabète</span> a été <strong>compté FAUX</strong> en annale comme cause d'ostéoporose secondaire (discordance) — à connaître.</div>\n\n      <p><strong>3 · Autres ostéoporoses secondaires</strong></p>\n      <table >\n        <thead><tr><th>Digestives</th><th>Générales</th><th>Génétiques &amp; médicaments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">Malabsorption</span> (résections, <span class=\"kw-etio\">maladie cœliaque</span>)</li>\n                <li>Entérocolopathie <span class=\"kw-etio\">inflammatoire</span> chronique</li>\n                <li><span class=\"kw-etio\">Cirrhose biliaire primitive</span></li>\n                <li><span class=\"kw-ttt\">Chirurgie</span> bariatrique, gastrectomie</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">PR</span>, spondylarthrite</li>\n                <li><span class=\"kw-etio\">Lupus</span> érythémateux disséminé</li>\n                <li><span class=\"kw-etio\">Myélome multiple</span>, mastocytose</li>\n                <li><span class=\"kw-etio\">Insuffisance rénale</span> (ostéodystrophie), hémodialyse</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">Ostéogénèse imparfaite</span>, Marfan, Ehler-Danlos, homocystinurie</li>\n                <li><span class=\"kw-ttt\">Médicaments</span> : <span class=\"kw-ttt\">corticoïdes</span>, hormones thyroïdiennes freinatrices, agonistes GnRH, anti-aromatases, anti-convulsivants, anti-calcineurines (<span class=\"kw-ttt\">ciclosporine</span>, <span class=\"kw-ttt\">tacrolimus</span>), <span class=\"kw-ttt\">HNF</span>, anti-rétroviraux</li>\n                <li><span class=\"kw-etio\">Alcool</span> (<span class=\"kw-chiffre\">≥ 3</span> unités/j), <span class=\"kw-etio\">tabac</span>, carence en <span class=\"kw-bio\">vitamine C</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 268 — Hypercalcémie · 242 — Hyperthyroïdie · 320 — Myélome multiple des os · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 124 — Ménopause - andropause</em></p>","frequence":6},{"id":"128-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les indications de l’ostéodensitométrie et des autres examens d’imagerie","contenu":"<div class=\"callout callout-info\"><strong>Technique.</strong> L'<span class=\"kw-imagerie\">absorptiométrie biphotonique aux rayons X (DXA)</span> est la technique de référence pour mesurer la <span class=\"kw-bio\">DMO</span> : peu irradiante, rapide, reproductible. La DMO est <strong>très prédictive</strong> du risque fracturaire — toute baisse de <span class=\"kw-chiffre\">− 1 DS</span> (ou −<span class=\"kw-chiffre\"> 10 %</span>) multiplie le risque par <span class=\"kw-chiffre\">2</span>.</div>\n\n      <p><strong>Sites de mesure</strong> (contenu cortical/trabéculaire différent) :</p>\n      <ul>\n        <li><strong>Rachis lombaire</strong> — riche en os <span class=\"kw-def\">trabéculaire</span>, le plus sensible en <span class=\"kw-clinique\">post-ménopause</span></li>\n        <li><strong>Extrémité supérieure du fémur (ESF)</strong> — plus <span class=\"kw-def\">corticale</span>, à privilégier après <span class=\"kw-chiffre\">65–70 ans</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Faux positifs.</strong> <span class=\"kw-clinique\">Les</span> lésions <span class=\"kw-imagerie\">arthrosiques</span> ou les <span class=\"kw-imagerie\">fractures vertébrales</span> augmentent artificiellement la mesure → mesurer alors préférentiellement à l'<strong>ESF chez la personne âgée</strong>.</div>\n\n      <p><strong>T-<span class=\"kw-def\">score</span> <span class=\"kw-bio\">vs</span> Z-score</strong></p>\n      <table >\n        <thead><tr><th>Indice</th><th>Référence</th><th>Usage</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">T-score</span></td><td>Écarts-types / adulte jeune de même sexe</td><td>Femmes et hommes <span class=\"kw-chiffre\">après 50 ans</span> — <span class=\"kw-chiffre\">ostéoporose si ≤ − 2,5</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Z-score</span></td><td>Écarts-types / sujet de même âge et sexe</td><td>Femmes non ménopausées, hommes &lt;<span class=\"kw-chiffre\"> 50 ans</span>, enfant — anormal si <span class=\"kw-chiffre\">&lt; − 2</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Indications remboursées de l'ostéodensitométrie (HAS)</strong></p>\n      <table >\n        <thead><tr><th>Situation</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1er examen — population générale</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Fracture vertébrale</span> sans contexte traumatique ni <span class=\"kw-etio\">tumoral</span></li>\n                <li>ATCD de <span class=\"kw-clinique\">fracture périphérique</span> sans traumatisme majeur (hors crâne, rachis cervical, doigts, orteils)</li>\n                <li><span class=\"kw-ttt\">Corticothérapie</span> ≥ <span class=\"kw-chiffre\">7,5 mg/j</span> &gt; <span class=\"kw-chiffre\">3 mois</span></li>\n                <li>Pathologies inductrices : hyperthyroïdie évolutive, hypercorticisme, hyperparathyroïdie primitive, hypogonadisme, ostéogénèse imparfaite</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Femme ménopausée (FR additionnels)</strong></td>\n            <td>ATCD familial de <span class=\"kw-clinique\">FESF</span> (1er degré) · <span class=\"kw-chiffre\">IMC &lt; 19</span> · ménopause <span class=\"kw-chiffre\">&lt; 40 ans</span> · <span class=\"kw-ttt\">corticothérapie</span> prolongée</td>\n          </tr>\n          <tr>\n            <td><strong>2e examen (<span class=\"kw-def\">suivi</span>)</strong></td>\n            <td>À l'arrêt d'un traitement anti-ostéoporotique ; ou <span class=\"kw-chiffre\">3 à 5 ans</span> après un 1er examen normal/ostéopénie modérée selon nouveaux FR</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 268 — Hypercalcémie · 124 — Ménopause - andropause</em></p>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/bone-mineral-density","label":"Radiopaedia : Densité minérale osseuse"}]},{"id":"128-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le bilan biologique de 1ère intention","contenu":"<div class=\"callout callout-info\"><strong>Règle clé.</strong> Au cours de l'ostéoporose commune, le bilan <span class=\"kw-ttt\">biologique</span> est <strong>le plus souvent normal</strong> — en particulier <span class=\"kw-bio\">calcémie</span> et <span class=\"kw-bio\">phosphatémie normales</span>. Son but est d'<strong>éliminer une ostéoporose secondaire ou un <span class=\"kw-def\">diagnostic différentiel</span></strong>. Il est <strong>inacceptable</strong> d'initier un traitement anti-ostéoporotique sans examens biologiques.</div>\n\n      <p><strong>Bilan <span class=\"kw-ttt\">biologique</span> de 1ʳᵉ intention</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">créatininémie</span> (avec estimation de la <span class=\"kw-bio\">clairance</span>)</li>\n        <li>Bilan hépatique : <span class=\"kw-bio\">ASAT</span>, <span class=\"kw-bio\">ALAT</span>, <span class=\"kw-bio\">γGT</span>, <span class=\"kw-bio\">phosphatases alcalines</span> (≠ <span class=\"kw-bio\">PAL</span> osseuses)</li>\n        <li><span class=\"kw-bio\">Calcémie</span>, <span class=\"kw-bio\">phosphatémie</span>, <span class=\"kw-bio\">25(OH)-vitamine D</span> (D2 + D3)</li>\n        <li><span class=\"kw-bio\">Électrophorèse des protéines sériques</span> (recherche d'un <span class=\"kw-etio\">pic monoclonal</span> → myélome)</li>\n      </ul>\n\n      <p><strong>Bilan de 2ᵉ intention</strong> (orienté selon le contexte)</p>\n      <table >\n        <thead><tr><th>Dosage</th><th>Cause recherchée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">PTH</span></td><td>Hyperparathyroïdie</td></tr>\n          <tr><td><span class=\"kw-bio\">TSH</span></td><td>Hyperthyroïdie ou surdosage thyroïdien</td></tr>\n          <tr><td><span class=\"kw-bio\">CST</span> (<span class=\"kw-bio\">coefficient de saturation</span> de la <span class=\"kw-bio\">transferrine</span>)</td><td><span class=\"kw-etio\">Hémochromatose</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Cortisolurie des 24 h</span></td><td>Hypercorticisme</td></tr>\n          <tr><td><span class=\"kw-bio\">Testostéronémie</span> (homme)</td><td>Hypogonadisme</td></tr>\n          <tr><td><span class=\"kw-bio\">Ac anti-transglutaminase</span></td><td><span class=\"kw-etio\">Maladie cœliaque</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-ttt\">Biopsie</span> osseuse (rang C).</strong> Exceptionnelle (double marquage à la tétracycline) : sujet jeune avec ostéoporose fracturaire à DMO peu abaissée sans cause, ou anomalies complexes du métabolisme osseux de l'insuffisant rénal.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 268 — Hypercalcémie · 320 — Myélome multiple des os</em></p>","frequence":5},{"id":"128-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les différentes mesures hygiéno-diététiques","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">mesures hygiéno-diététiques (MHD)</span> sont la base de la prise en charge et de la prévention, à mettre en œuvre <strong>tout au long de la vie</strong>.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Mode de vie</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Activité physique régulière « en charge »</span> (préserve le capital osseux)</li>\n                <li>Arrêt du <span class=\"kw-etio\">tabac</span> et de l'<span class=\"kw-etio\">alcool</span></li>\n                <li><span class=\"kw-alerte\">Prévention des chutes</span> ; protecteur de hanche (efficacité limitée par l'observance)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Calcium</strong></td>\n            <td>\n              <ul>\n                <li>Apports calciques de <span class=\"kw-chiffre\">1 – 1,2 g/jour</span> (à évaluer par un <span class=\"kw-clinique\">questionnaire</span>)</li>\n                <li>Privilégier <span class=\"kw-clinique\">les</span> apports <strong>naturels</strong> : <span class=\"kw-chiffre\">≥ 1</span> produit laitier par repas, eaux fortement minéralisées (Contrex®, Hépar®, Courmayeur®)</li>\n                <li>Le calcium per os est mal toléré (<span class=\"kw-clinique\">nausées</span>, constipation) → mauvaise observance</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vitamine D</strong></td>\n            <td>\n              <ul>\n                <li>Objectif de concentration sérique <span class=\"kw-chiffre\">≥ 30 ng/mL</span></li>\n                <li><span class=\"kw-ttt\">Supplémentation</span> en cas de carence (ex. protocole de Souberbielle)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 250 — Dénutrition · 252 — Troubles nutritionnels du sujet âgé · 131 — Troubles de la marche et de l'équilibre du sujet âgé</em></p>","frequence":2},{"id":"128-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement médicamenteux d’une ostéoporose","contenu":"<div class=\"callout callout-info\"><strong>Préalables.</strong> La mesure de la <span class=\"kw-bio\">DMO</span> et un <span class=\"kw-bio\">bilan biologique</span> sont nécessaires <strong>avant toute décision thérapeutique</strong>. <span class=\"kw-clinique\">Les</span> traitements diminuent le risque de fracture vertébrale de <span class=\"kw-chiffre\">40–70 %</span> et de fracture périphérique de <span class=\"kw-chiffre\">30–40 %</span> (jusqu'à<span class=\"kw-chiffre\"> 50 %</span> pour la FESF).</div>\n\n      <p><strong><span class=\"kw-clinique\">Les</span> molécules</strong></p>\n      <table >\n        <thead><tr><th>Classe</th><th>Effet / place</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Bisphosphonates</span> (alendronate, risédronate per os ; <span class=\"kw-ttt\">acide zolédronique</span> IV <span class=\"kw-chiffre\">1×/an</span>)</td>\n            <td>Anti-résorbeurs — <strong>1ʳᵉ intention</strong>. Diminuent fractures <span class=\"kw-clinique\">vertébrales et périphériques</span> dont FESF, sans limite d'âge</td>\n            <td>EI : <span class=\"kw-alerte\">ostéonécrose de la mâchoire</span> (rare), syndrome pseudo-grippal (formes IV), fractures fémorales atypiques. <span class=\"kw-ci\">CI</span> : ATCD d'œsophagite (per os), <span class=\"kw-bio\">clairance</span> &lt;<span class=\"kw-chiffre\"> 30 mL</span>/min, hypocalcémie</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Dénosumab</span> (Ac anti-RANKL, SC <span class=\"kw-chiffre\">tous les 6 mois</span>)</td>\n            <td>Anti-résorbeur — <strong>2ᵉ intention</strong> / relais des bisphosphonates (utilisable si <span class=\"kw-bio\">clairance</span> <span class=\"kw-chiffre\">≥ 15 mL</span>/min)</td>\n            <td><span class=\"kw-alerte\">Effet rebond à l'arrêt</span> (↑ risque fracturaire) → <strong>relais obl<span class=\"kw-chiffre\">iga</span>toire par bisphosphonate <span class=\"kw-chiffre\">≥ 1 an</span></strong>. <span class=\"kw-ci\">CI</span> : hypocalcémie</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Tériparatide</span> (fragment 1-34 de la <span class=\"kw-bio\">PTH</span>, SC)</td>\n            <td><strong>Ostéoformateur</strong> — remboursé pour <span class=\"kw-clinique\">les</span> formes sévères avec <span class=\"kw-chiffre\">≥ 2 fractures vertébrales</span> (1ʳᵉ intention dans cette indication)</td>\n            <td><span class=\"kw-chiffre\">18–24 mois</span> puis relais anti-résorbeur. <span class=\"kw-ci\">CI</span> : hypercalcémie, Paget, ostéomalacie, tumeur osseuse, ATCD de <span class=\"kw-ttt\">radiothérapie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Raloxifène</span> (SERM)</td>\n            <td>Diminue <span class=\"kw-clinique\">les</span> fractures <span class=\"kw-clinique\">vertébrales</span> seulement (pas périphériques)</td>\n            <td>Femme ménopausée, remboursé jusqu'à <span class=\"kw-chiffre\">≤ 70 ans</span>. <span class=\"kw-ci\">CI/risque</span> : MTEV ; non utilisé chez l'homme</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">THM</span> (traitement hormonal de la ménopause)</td>\n            <td>Effet sur <span class=\"kw-clinique\">les</span> fractures <span class=\"kw-clinique\">vertébrales</span> ; n'est plus indiqué pour l'ostéoporose isolée</td>\n            <td>Réservé aux troubles climatériques, femmes de <span class=\"kw-chiffre\">50–60 ans</span>. Risques : MTEV, néoplasie mammaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Indications selon le T-<span class=\"kw-def\">score</span> et le type de fracture</strong> (mesure de la DMO indispensable)</p>\n      <table >\n        <thead><tr><th>T-score</th><th>Fracture sévère</th><th>Fracture non sévère</th><th>Absence de fracture</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">T &gt; − 1</span></td><td>Avis spécialisé</td><td>Pas de traitement</td><td>Pas de traitement</td></tr>\n          <tr><td><span class=\"kw-chiffre\">− 2 &lt; T ≤ − 1</span></td><td><strong>Traitement</strong></td><td>Avis spécialisé</td><td>Pas de traitement</td></tr>\n          <tr><td><span class=\"kw-chiffre\">− 3 &lt; T ≤ − 2</span></td><td><strong>Traitement</strong></td><td><strong>Traitement</strong></td><td>Avis spécialisé</td></tr>\n          <tr><td><span class=\"kw-chiffre\">T ≤ − 3</span></td><td><strong>Traitement</strong></td><td><strong>Traitement</strong></td><td><strong>Traitement</strong></td></tr>\n        </tbody>\n      </table>\n      <p style=\"font-size:13px\"><em>Fracture sévère (traitement impératif quel que soit l'âge) : vertèbre, FESF, FESH, bassin, fémur, tibia proximal, <span class=\"kw-chiffre\">≥ 3</span> côtes.</em></p>\n\n      <div class=\"callout callout-warn\"><strong>Précautions des bisphosphonates oraux.</strong> Prise le <span class=\"kw-clinique\">matin à jeun</span>, debout/assis, avec un grand verre d'<span class=\"kw-clinique\">eau du robinet (non minéralisée)</span>, à distance de toute prise alimentaire/médicamenteuse ; <strong>ne pas se recoucher dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">30 min</span></strong> (prévention de l'œsophagite). <span class=\"kw-def\">Suivi</span> <span class=\"kw-clinique\">dentaire</span> régulier (prévention de l'ostéonécrose).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span> · 124 — Ménopause - andropause</em></p>","frequence":5,"liens":[{"href":"https://www.has-sante.fr/jcms/c_1751307/fr/les-medicaments-de-l-osteoporose","label":"HAS : les médicaments de l'ostéoporose"},{"href":"https://pharmacomedicale.org/medicaments/par-specialites/category/antiosteoporose","label":"Pharmacomédicale : anti-ostéoporose"}]},{"id":"128-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie en radiographie d’une fracture ostéoporotique","contenu":"<div class=\"callout callout-info\"><strong>Quand évoquer.</strong> Devant <strong>toute fracture</strong> survenant après un <span class=\"kw-clinique\">traumatisme à bas niveau d'énergie</span> (ex. chute de sa hauteur) après <span class=\"kw-chiffre\">50 ans</span> — sauf sur <span class=\"kw-clinique\">les</span> sites non concernés.</div>\n\n      <p><strong>Sites non concernés</strong> (jamais ostéoporotiques) : <span class=\"kw-imagerie\">crâne</span>, <span class=\"kw-imagerie\">face</span>, rachis cervical, <span class=\"kw-imagerie\">T1–T3</span>, doigts, orteils.</p>\n\n      <p><strong>Types de fractures</strong></p>\n      <table >\n        <thead><tr><th>Type</th><th>Contrainte</th><th>Os / squelette</th><th>Exemple</th></tr></thead>\n        <tbody>\n          <tr><td>Traumatique</td><td>Brutale, intense</td><td>Normal / normal</td><td>—</td></tr>\n          <tr><td>Pathologique</td><td>Banale</td><td><span class=\"kw-imagerie\">Pathologique</span> / normal</td><td>Métastase, Paget</td></tr>\n          <tr><td>Contrainte (fatigue/stress)</td><td>Inhabituelles, répétées</td><td>Normal / normal</td><td>Surentraînement</td></tr>\n          <tr><td><strong>Insuffisance / fragilité</strong></td><td>Banale</td><td><span class=\"kw-imagerie\">Pathologique</span> / <span class=\"kw-imagerie\">pathologique</span></td><td><strong>Ostéoporose</strong></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Sémiologie RX de la fracture vertébrale ostéoporotique.</strong> Seules <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">radiographies</span> permettent le diagnostic :\n        <ul>\n          <li>Fracture située <span class=\"kw-imagerie\">sous T3</span></li>\n          <li><span class=\"kw-imagerie\">Absence d'ostéolyse</span> — ⭐ <strong>signe du puzzle</strong> : bien que fracturée, la <strong>corticale de la vertèbre peut être suivie sur toute sa longueur</strong></li>\n          <li><span class=\"kw-imagerie\">Respect du mur vertébral postérieur</span> et de l'arc postérieur (pédicules) — à la différence de la <span class=\"kw-alerte\">vertèbre borgne</span> (non-visualisation des pédicules = signe de malignité)</li>\n          <li>Déminéralisation <span class=\"kw-imagerie\">homogène</span> (≠ lacunes de la métastase)</li>\n        </ul>\n      </div>\n\n      <p><strong>Fractures sévères <span class=\"kw-bio\">vs</span> majeures</strong></p>\n      <table >\n        <thead><tr><th>Fractures sévères (excès de morbi-<span class=\"kw-def\">mortalité</span>)</th><th>Fractures majeures (forte <span class=\"kw-def\">incidence</span>)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>FESF, FEIF, FESH, vertèbres, bassin (sacrum, branches ilio-/ischio-pubiennes), diaphyse fémorale, tibia proximal, <span class=\"kw-chiffre\">≥ 3</span> côtes</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Poignet</span> (Pouteau-Colles) : dès <span class=\"kw-chiffre\">50 ans</span>, signal d'alarme précoce</li>\n                <li>Fracture <span class=\"kw-clinique\">vertébrale</span> clinique : dès <span class=\"kw-chiffre\">65 ans</span></li>\n                <li><span class=\"kw-clinique\">FESF</span> : dès <span class=\"kw-chiffre\">70 ans</span></li>\n                <li>FESH (humérus proximal)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Cliniquement</strong> : rachialgies <span class=\"kw-clinique\">mécaniques</span> aiguës (régressent en <span class=\"kw-chiffre\">4–6 semaines</span>), <span class=\"kw-clinique\">perte de taille</span> (<span class=\"kw-chiffre\">≥ 4 cm</span> ou <span class=\"kw-chiffre\">≥ 2 cm</span> prospective), <span class=\"kw-clinique\">cyphose</span> ; état général conservé et <span class=\"kw-clinique\">examen neurologique normal</span> (respect du mur postérieur). Asymptomatique possible.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 94 — Rachialgie · 320 — Myélome multiple des os</em></p>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/trochanteric-fracture","label":"Radiopaedia : fracture per-trochantérienne"},{"href":"https://radiopaedia.org/articles/neck-of-femur-fracture-1","label":"Radiopaedia : fracture du col fémoral"}]},{"id":"128-10","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie d’ostéoporose avec fracture vertébrale","contenu":"<div class=\"callout callout-info\"><strong>À reconnaître sur la <span class=\"kw-imagerie\">radiographie</span>.</strong> Tassement vertébral sur fracture ostéoporotique, à différencier d'un tassement malin.</div>\n      <ul>\n        <li><span class=\"kw-imagerie\">Déminéralisation osseuse homogène</span> (hypertransparence diffuse)</li>\n        <li><span class=\"kw-imagerie\">Tassement / cunéiformisation</span> d'un corps vertébral situé <span class=\"kw-imagerie\">sous T3</span></li>\n        <li>⭐ <strong>Signe du puzzle</strong> : <span class=\"kw-imagerie\">corticale continue, suivie sur toute sa longueur</span> (pas d'ostéolyse)</li>\n        <li><span class=\"kw-imagerie\">Respect du mur postérieur</span> et des <span class=\"kw-imagerie\">pédicules</span> (≠ vertèbre borgne maligne)</li>\n        <li>Absence de <span class=\"kw-clinique\">masse</span> des parties molles, absence de lyse</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/128/rx-rachis-lombaire-osteoporose-face.png\" alt=\"Radiographie du rachis lombaire de face — fractures-tassements ostéoporotiques, déminéralisation homogène, corticale continue\" loading=\"lazy\">\n        <figcaption>Rachis lombaire de face : fractures-tassements ostéoporotiques (T11, L1), déminéralisation homogène, corticale continue (signe du puzzle), pas de lyse. Source : IMAGERIE A CONNAITRE (EDN item 128, p.16).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/128/rx-rachis-lombaire-osteoporose-profil.png\" alt=\"Radiographie du rachis lombaire de profil — tassement cunéiforme, respect du mur postérieur\" loading=\"lazy\">\n        <figcaption>Rachis lombaire de profil : tassement cunéiforme du plateau supérieur, respect du mur postérieur. Source : IMAGERIE A CONNAITRE (EDN item 128, p.16).</figcaption>\n      </figure>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/spinal-compression-fracture","label":"Radiopaedia : fracture vertébrale par compression"}]},{"id":"128-11","rang":"B","rubrique":"Contenu multimédia","titre":"IRM d’ostéoporose avec fracture vertébrale","contenu":"<div class=\"callout callout-info\"><strong>Intérêt de l'<span class=\"kw-imagerie\">IRM</span>.</strong> En cas de doute, différencier une fracture <span class=\"kw-def\">ostéoporotique</span> bénigne d'une fracture sur <span class=\"kw-alerte\">métastase</span>.</div>\n      <table >\n        <thead><tr><th><span class=\"kw-imagerie\">IRM</span></th><th>Fracture ostéoporotique</th><th>Métastase ostéolytique</th><th>Métastase ostéocondensante</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">T1</span></td><td>Hyposignal</td><td>Hyposignal</td><td>Hyposignal</td></tr>\n          <tr><td><span class=\"kw-imagerie\">T2</span></td><td>Hypersignal</td><td>Hypersignal</td><td><strong>Hyposignal</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Critères discriminants.</strong> Le signal T1/T2 seul ne sépare pas ostéoporose et métastase ostéolytique ; retenir :\n        <ul>\n          <li><span class=\"kw-imagerie\">Rehaussement après gadolinium</span> : <strong>important si métastase</strong>, modéré/homogène si tassement bénin</li>\n          <li><span class=\"kw-imagerie\">Hypersignal T2 « en bande »</span> → ostéoporose ; <span class=\"kw-imagerie\">hypersignal diffus « en mottes »</span> → métastase</li>\n          <li>Respect du <span class=\"kw-imagerie\">mur postérieur</span> et des pédicules en faveur du bénin</li>\n        </ul>\n      </div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/128/irm-rachis-lombaire-osteoporose-t1.png\" alt=\"IRM sagittale du rachis lombaire séquence T1 — tassement de L1 en hyposignal\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">IRM</span> rachis lombaire sagittale T1 : tassement de L1, <span class=\"kw-clinique\">œdème</span> osseux en hyposignal. Source : IMAGERIE A CONNAITRE (EDN item 128, p.17).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/128/irm-rachis-lombaire-osteoporose-t2-fatsat.png\" alt=\"IRM sagittale du rachis lombaire séquence T2 Fat Sat — œdème de L1 en hypersignal, aspect bénin ostéoporotique\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">IRM</span> rachis lombaire sagittale T2 Fat Sat : œdème de L1 en hypersignal, recul modéré du coin postéro-supérieur, aspect bénin ostéoporotique. Source : IMAGERIE A CONNAITRE (EDN item 128, p.17).</figcaption>\n      </figure>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/osteoporotic-vs-pathological-vertebral-fractures","label":"Radiopaedia : fracture ostéoporotique vs pathologique (IRM)"}]},{"id":"128-12","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’ostéomalacie","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> L'<span class=\"kw-def\">ostéomalacie</span> est une ostéopathie <span class=\"kw-def\">diffuse, raréfiante et fragilisante</span> du tissu osseux, distincte de l'ostéoporose :</div>\n      <ul>\n        <li><strong><span class=\"kw-def\">Physiopathologie</span></strong> : <span class=\"kw-def\">retard de minéralisation</span> de la matrice organique (tissu ostéoïde) nouvellement formée</li>\n        <li><strong>Causes</strong> : concentrations insuffisantes en <span class=\"kw-bio\">calcium</span>, <span class=\"kw-bio\">phosphore</span> et <span class=\"kw-bio\">vitamine D</span> (nécessaires à la minéralisation)</li>\n        <li><strong>Conséquence</strong> : accumulation de tissu <span class=\"kw-def\">ostéoïde non minéralisé</span> → <span class=\"kw-clinique\">os « mou »</span>, à résistance mécanique diminuée</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Rachitisme</strong> = ostéomalacie de l'<strong>enfant</strong> (déficit sévère en <span class=\"kw-bio\">vitamine D</span> et/ou calcium), aux périodes de forte croissance.</div>\n\n      <p><strong>Rappel — métabolisme de la <span class=\"kw-bio\">vitamine D</span></strong> (vitamine liposoluble) :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Sources</td><td><span class=\"kw-clinique\">Synthèse cutanée</span> sous <span class=\"kw-etio\">UV</span> (7-déhydrocholestérol → vitamine D3) ++ ; alimentation (huile de foie de morue)</td></tr>\n          <tr><td>1ʳᵉ hydroxylation (foie)</td><td>→ <span class=\"kw-bio\">calcidiol</span> (25-OH-vitamine D) = forme de réserve dosée</td></tr>\n          <tr><td>2ᵉ hydroxylation (rein, 1α-hydroxylase)</td><td>→ <span class=\"kw-bio\">calcitriol</span> (1,25-OH-vitamine D) = <strong>forme active</strong></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/osteomalacia","label":"Radiopaedia : Osteomalacia"}]},{"id":"128-13","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques et biologiques devant faire évoquer le diagnostic d’ostéomalacie","contenu":"<p><strong>Arguments cliniques</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Myopathie proximale</span> (≈ <span class=\"kw-chiffre\">50 %</span>) : impotence fonctionnelle <strong>sans aucun signe neurologique déficitaire</strong></li>\n        <li><span class=\"kw-clinique\">Douleurs osseuses</span> : installation insidieuse, rythme <span class=\"kw-clinique\">mécanique</span>, topographie <span class=\"kw-clinique\">pelvi-crurale</span> initiale puis extension (thoracique, scapulaire, rachidienne, membres) avec aggravation progressive</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Arguments biologiques</strong> (grande valeur diagnostique dans l'ostéomalacie par carence en <span class=\"kw-bio\">vitamine D</span>) :\n        <ul>\n          <li><span class=\"kw-bio\">Hypocalcémie</span>, <span class=\"kw-bio\">hypocalciurie</span>, <span class=\"kw-bio\">hypophosphorémie</span></li>\n          <li><span class=\"kw-bio\">Effondrement de la 25(OH)-vitamine D</span> &lt; <span class=\"kw-chiffre\">5 ng/mL</span></li>\n          <li>Élévation des <span class=\"kw-bio\">phosphatases alcalines</span> (osseuses)</li>\n          <li><span class=\"kw-bio\">Hyperparathyroïdie secondaire</span> à l'hypocalcémie</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\"><strong>Arguments d'imagerie (rang C).</strong> <span class=\"kw-clinique\">Les</span> signes peuvent manquer au début (leur absence n'écarte pas le diagnostic) :\n        <ul>\n          <li>Hypertransparence osseuse, aspect <span class=\"kw-imagerie\">flou « cotonneux »</span> des contours</li>\n          <li>⭐ <span class=\"kw-imagerie\">Stries de Looser-Milkman</span> : bandes radiotransparentes rectilignes/sinueuses (<span class=\"kw-chiffre\">2–3 mm</span>), <strong>perpendiculaires à la corticale qu'elles interrompent</strong>, <span class=\"kw-imagerie\">bilatérales et symétriques</span> (branches ilio-/ischio-pubiennes, bord interne des fémurs proximaux) ; <span class=\"kw-imagerie\">hyperfixation</span> à la <span class=\"kw-imagerie\">scintigraphie</span></li>\n        </ul>\n      </div>\n\n      <p><strong>Diagnostic de la carence en <span class=\"kw-bio\">vitamine D</span></strong> (dosage de la 25(OH)-vitamine D)</p>\n      <table >\n        <thead><tr><th>Statut</th><th>25(OH)-vitamine D</th></tr></thead>\n        <tbody>\n          <tr><td>Carence</td><td><span class=\"kw-chiffre\">&lt; 10 ng/mL</span></td></tr>\n          <tr><td>Insuffisance</td><td><span class=\"kw-chiffre\">10 – 30 ng/mL</span></td></tr>\n          <tr><td>Recommandée</td><td><span class=\"kw-chiffre\">30 – 70 ng/mL</span></td></tr>\n          <tr><td>Risque d'intoxication</td><td><span class=\"kw-chiffre\">&gt; 150 ng/mL</span></td></tr>\n        </tbody>\n      </table>\n      <p style=\"font-size:13px\"><em>Traitement : adapter à l'étiologie (ex. régime sans <span class=\"kw-etio\">gluten</span> si maladie cœliaque) ; en cas de carence d'apport, supplémentation en <span class=\"kw-bio\">vitamine D</span> et calcium.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 250 — Dénutrition</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/rickets","label":"Radiopaedia : Rickets (rachitisme)"}]}],"astuces":[],"strategie":{"hospit":"<p><strong>Cadre :</strong> prise en charge <span class=\"kw-def\">ambulatoire</span>, l'ostéoporose étant une maladie silencieuse jusqu'à l'événement fracturaire<br><strong>Bilan préalable :</strong> <span class=\"kw-imagerie\">ostéodensitométrie (DMO)</span> et <span class=\"kw-bio\">examens biologiques</span> obl<span class=\"kw-chiffre\">iga</span>toires avant toute décision thérapeutique<br><strong>Avis spécialisé :</strong> recours au <span class=\"kw-etio\">spécialiste de pathologie osseuse</span> + <span class=\"kw-chiffre\">FRAX</span> dans <span class=\"kw-clinique\">les</span> zones intermédiaires de T-<span class=\"kw-def\">score</span><br><strong>Prescription encadrée :</strong> initiation du <span class=\"kw-ttt\">dénosumab</span> par un médecin spécialiste de l'ostéoporose</p>","redflags":"<ul><li><span class=\"kw-alerte\">Fracture sévère</span> (<span class=\"kw-etio\">vertèbre</span>, <span class=\"kw-etio\">FESF</span>, <span class=\"kw-etio\">FESH</span>, bassin) : excès de morbi-<span class=\"kw-def\">mortalité</span>, impose un traitement</li><li><span class=\"kw-alerte\">Excès de mortalité de la FESF</span>, particulièrement chez l'homme</li><li><span class=\"kw-clinique\">Altération de l'état général</span> ou <span class=\"kw-clinique\">douleur inflammatoire</span> avec <span class=\"kw-etio\">ATCD de cancer</span> → évoquer une <span class=\"kw-etio\">métastase</span></li><li><span class=\"kw-radio\">Ostéolyse</span> ou non-visualisation des pédicules (<span class=\"kw-radio\">vertèbre borgne</span>) : <span class=\"kw-alerte\">signe de malignité</span></li><li><span class=\"kw-bio\">Pic monoclonal</span> + <span class=\"kw-bio\">hypercalcémie</span> → <span class=\"kw-etio\">myélome multiple</span></li><li><span class=\"kw-bio\">Calcémie</span> ou <span class=\"kw-bio\">phosphatémie</span> anormale : élimine une ostéoporose commune (normales dans l'ostéoporose)</li><li>Fracture d'un <span class=\"kw-etio\">site non concerné</span> par l'ostéoporose (crâne, face, rachis cervical, &lt; T4, doigts, orteils) → chercher une autre cause</li></ul>","principes":"<p>Mesures hygiéno-diététiques systématiques, puis traitement <span class=\"kw-etio\">médicamenteux</span> indiqué selon le statut fracturaire et le seuil de T-<span class=\"kw-def\">score</span>.</p><p><strong>Mesures hygiéno-diététiques (systématiques)</strong></p><ul><li><span class=\"kw-ttt\">Activité physique régulière en charge</span>, <span class=\"kw-ttt\">arrêt du tabac et de l'alcool</span></li><li><span class=\"kw-ttt\">Prévention des chutes</span> (± protecteur de hanche, observance limitée)</li><li><span class=\"kw-ttt\">Apports calciques</span> <span class=\"kw-chiffre\">1 à 1,2 g/jour</span>, à privilégier par voie naturelle (produits laitiers, eaux fortement minéralisées)</li><li><span class=\"kw-ttt\">Supplémentation en vitamine D</span> pour une cible <span class=\"kw-chiffre\">≥ 30 ng/mL</span></li></ul><p><strong>Indication du traitement (fracture × T-<span class=\"kw-def\">score</span>)</strong></p><p>DMO et bilan <span class=\"kw-ttt\">biologique</span> obl<span class=\"kw-chiffre\">iga</span>toires avant toute mise en route du traitement</p><ul><li><span class=\"kw-alerte\">Fracture sévère</span> : traitement impératif quel que soit l'âge (si <span class=\"kw-chiffre\">T-score ≤ -1</span> ; sinon avis spécialisé)</li><li>Fracture non sévère : traitement si <span class=\"kw-chiffre\">T-score ≤ -2</span></li><li>Absence de fracture : traitement si <span class=\"kw-chiffre\">T-score ≤ -3</span></li><li>Zones intermédiaires de T-<span class=\"kw-def\">score</span> → <span class=\"kw-etio\">avis du spécialiste osseux</span> + <span class=\"kw-chiffre\">FRAX</span></li></ul><p><strong>Moyens <span class=\"kw-etio\">médicamenteux</span></strong></p><p><span class=\"kw-ci\">ATCD d'œsophagite</span> et <span class=\"kw-ci\">insuffisance rénale sévère (&lt; 30 mL/min)</span> contre-indiquent <span class=\"kw-clinique\">les</span> bisphosphonates oraux</p><ul><li><span class=\"kw-ttt\">Bisphosphonates</span> (alendronate, risédronate, <span class=\"kw-ttt\">acide zolédronique IV</span> <span class=\"kw-chiffre\">1x/an</span>) : <span class=\"kw-chiffre\">1ère intention</span>, ↓ fractures vertébrales et périphériques dont la FESF</li><li><span class=\"kw-ttt\">Dénosumab</span> : relais/<span class=\"kw-chiffre\">2e intention</span> ; <span class=\"kw-ci\">hypocalcémie contre-indiquée</span> ; <span class=\"kw-alerte\">rebond à l'arrêt</span> imposant un relais par bisphosphonate <span class=\"kw-chiffre\">≥ 1 an</span></li><li><span class=\"kw-ttt\">Tériparatide</span> : si <span class=\"kw-chiffre\">≥ 2 fractures vertébrales</span> (<span class=\"kw-chiffre\">1ère intention</span> dans cette indication)</li><li><span class=\"kw-ttt\">Raloxifène</span> et <span class=\"kw-ttt\">THM</span> : femme ménopausée, ↓ fractures vertébrales seulement (THM si <span class=\"kw-chiffre\">50-60 ans</span> + troubles climatériques)</li></ul>","suivi":"<p><strong>Clinique :</strong> nouvelles fractures, nouveaux FR, risque de chute, tolérance, <span class=\"kw-clinique\">mesure de la taille</span> <span class=\"kw-chiffre\">1x/an</span><br><strong>Densitométrie :</strong> <span class=\"kw-imagerie\">DMO</span> de contrôle <span class=\"kw-chiffre\">2 à 3 ans</span> après le début, puis en fin de séquence<br><strong>Marqueurs du remodelage :</strong> <span class=\"kw-bio\">P1NP</span> (formation), <span class=\"kw-bio\">CTX</span> (résorption) — pour l'observance et la réponse, pas pour le diagnostic<br><strong>Durée :</strong> cycle de <span class=\"kw-chiffre\">3 à 5 ans</span> ; arrêt si pas de nouvelle fracture, pas de nouveau FR et DMO stable / T-<span class=\"kw-def\">score</span> cible atteint</p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-7-0.php","label":"Collège : Cofer — Item 128"},{"href":"https://radiopaedia.org/articles/osteoporosis-3","label":"Radiopaedia : Osteoporosis"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"<span class=\"kw-alerte\">Fracture à bas niveau d'énergie</span> après <span class=\"kw-chiffre\">50 ans</span>, ou <span class=\"kw-def\">facteur de risque</span> / <span class=\"kw-imagerie\">découverte densitométrique</span> — Radiographies + bilan <span class=\"kw-ttt\">biologique</span> de <span class=\"kw-chiffre\">1ère intention</span> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">phosphatémie</span>, <span class=\"kw-bio\">PAL</span>, <span class=\"kw-bio\">25-OH-vitamine D</span>, <span class=\"kw-bio\">EPP</span>","detail":"<h4>CAT — Ostéopathie fragilisante : du <span class=\"kw-def\">dépistage</span> au traitement — Confirmer l'ostéoporose, éliminer <span class=\"kw-clinique\">les</span> diagnostics différentiels, traiter selon fracture × T-<span class=\"kw-def\">score</span></h4>","branches":[{"to":"t-diff","label":"Anomalie biologique ou signe de malignité","color":"blue"},{"to":"q-fracture","label":"Calcémie + phosphatémie normales, pas de signe de malignité","color":"green"}]},{"id":"t-diff","kind":"terminal","label":"Rechercher un diagnostic différentiel ou une ostéoporose secondaire","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-etio\">Myélome multiple</span> : <span class=\"kw-bio\">pic monoclonal</span> + <span class=\"kw-bio\">hypercalcémie</span></li><li><span class=\"kw-etio\">Métastase</span> : <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">douleur inflammatoire</span>, <span class=\"kw-etio\">ATCD de cancer</span>, <span class=\"kw-radio\">ostéolyse</span> / <span class=\"kw-radio\">vertèbre borgne</span></li><li><span class=\"kw-etio\">Ostéomalacie</span> : <span class=\"kw-bio\">25-OH-vitamine D effondrée &lt; 5 ng/mL</span>, <span class=\"kw-bio\">hypocalcémie</span>, <span class=\"kw-bio\">hypophosphorémie</span>, <span class=\"kw-bio\">PAL augmentées</span></li></ul><h4>Paraclinique</h4><ul><li>Bilan de <span class=\"kw-chiffre\">2e intention</span> : <span class=\"kw-bio\">PTH</span>, <span class=\"kw-bio\">TSH</span>, <span class=\"kw-bio\">CST</span>, <span class=\"kw-bio\">cortisolurie des 24h</span>, <span class=\"kw-bio\">testostérone</span> (homme), <span class=\"kw-bio\">Ac anti-transglutaminase</span></li><li><span class=\"kw-imagerie\">TDM</span> / <span class=\"kw-imagerie\">IRM</span> si doute sur une origine <span class=\"kw-etio\">tumorale</span></li></ul>"},{"id":"q-fracture","kind":"decision","label":"Ostéoporose confirmée (<span class=\"kw-imagerie\">DMO</span>) — quel statut fracturaire ? — Mesure de la DMO et bilan <span class=\"kw-ttt\">biologique</span> obl<span class=\"kw-chiffre\">iga</span>toires avant toute décision thérapeutique","branches":[{"to":"t-severe","label":"Fracture sévère (vertèbre, FESF, FESH, bassin)","color":"red"},{"to":"t-nonsev","label":"Fracture non sévère (ex. poignet)","color":"amber"},{"to":"t-nofx","label":"Absence de fracture (FR + DXA)","color":"green"}]},{"id":"t-severe","kind":"terminal","label":"Traitement anti-ostéoporotique impératif (quel que soit l'âge)","color":"red","detail":"<h4>Seuil</h4><ul><li>Traitement si <span class=\"kw-chiffre\">T-score ≤ -1</span></li><li>Si <span class=\"kw-chiffre\">T-score &gt; -1</span> : <span class=\"kw-etio\">avis du spécialiste osseux</span> + <span class=\"kw-chiffre\">FRAX</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Bisphosphonate</span> per os ou IV en <span class=\"kw-chiffre\">1ère intention</span> ; <span class=\"kw-ttt\">dénosumab</span> si échec/<span class=\"kw-ci\">intolérance</span></li><li><span class=\"kw-ttt\">Tériparatide</span> si <span class=\"kw-chiffre\">≥ 2 fractures vertébrales</span></li><li><span class=\"kw-ttt\">THM</span> si <span class=\"kw-chiffre\">50-60 ans</span> + troubles climatériques</li></ul><h4>Conduite</h4><ul><li>Toujours associer <span class=\"kw-ttt\">MHD</span> + <span class=\"kw-ttt\">calcium</span> + <span class=\"kw-ttt\">vitamine D</span></li></ul>"},{"id":"t-nonsev","kind":"terminal","label":"Fracture non sévère : traiter si T-score ≤ -2","color":"amber","detail":"<h4>Seuil</h4><ul><li><span class=\"kw-chiffre\">T-score ≤ -2</span> → traitement</li><li><span class=\"kw-chiffre\">-2 &lt; T-score ≤ -1</span> → <span class=\"kw-etio\">avis spécialisé</span> + <span class=\"kw-chiffre\">FRAX</span></li><li><span class=\"kw-chiffre\">T-score &gt; -1</span> → pas de traitement</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Bisphosphonate</span> per os ou IV, <span class=\"kw-ttt\">dénosumab</span></li><li><span class=\"kw-ttt\">Raloxifène</span> (risque périphérique faible, <span class=\"kw-chiffre\">&lt; 70 ans</span>) ou <span class=\"kw-ttt\">THM</span> (<span class=\"kw-chiffre\">50-60 ans</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">MHD</span> + <span class=\"kw-ttt\">calcium</span> + <span class=\"kw-ttt\">vitamine D</span> systématiques</li></ul>"},{"id":"t-nofx","kind":"terminal","label":"Absence de fracture : traiter si T-score ≤ -3","color":"green","detail":"<h4>Seuil</h4><ul><li><span class=\"kw-chiffre\">T-score ≤ -3</span> → traitement</li><li><span class=\"kw-chiffre\">-3 &lt; T-score ≤ -2</span> → <span class=\"kw-etio\">avis spécialisé</span> + <span class=\"kw-chiffre\">FRAX</span></li><li><span class=\"kw-chiffre\">T-score &gt; -2</span> → pas de traitement</li></ul><h4>Traitement</h4><ul><li>Si indiqué : <span class=\"kw-ttt\">bisphosphonate</span>, <span class=\"kw-ttt\">raloxifène</span>, <span class=\"kw-ttt\">dénosumab</span> ou <span class=\"kw-ttt\">THM</span> selon le profil</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">MHD</span>, correction <span class=\"kw-ttt\">calcium</span> / <span class=\"kw-ttt\">vitamine D</span>, <span class=\"kw-ttt\">prévention des chutes</span></li></ul>"}]},"cards":[{"i":"15ca32337b38","n":128,"o":"128-1","u":"Définition","t":"Connaître la définition de l’ostéoporose (densitométrique et fractures)","q":"Comment l'ostéoporose densitométrique est-elle définie selon le T-score à l'ostéodensitométrie (DXA) ?","a":"<p>L'ostéoporose densitométrique est définie par un <stong>T-score ≤ -2,5</stong> au col fémoral, mesuré par ostéodensitométrie (DXA). À noter les autres catégories :</p> <ul><li>DMO normale : T-score > -1</li><li>Ostéopénie (densité intermédiaire) : entre -2,5 et -1</li><li>Ostéoporose sévère / confirmée : T-score ≤ -2,5 et au moins une fracture ostéoporotique</li></ul>"},{"i":"5554b6b2dbbf","n":128,"o":"128-1","u":"Définition","t":"Connaître la définition de l’ostéoporose (densitométrique et fractures)","q":"Quelle est la limite de la définition densitométrique de l'ostéoporose et quel est le rôle de la fracture dans cette pathologie ?","a":"<p>La moitié des fractures ostéoporotiques surviennent chez des patients dont la DMO (densité minérale osseuse) est <stong>supérieure à -2,5</stong>.<br>La DMO est à considérer comme un <stong>facteur de risque majeur de fracture</stong>, mais pas comme une condition nécessaire et suffisante.</p><p>L'épisode fracturaire est la <stong>complication de la maladie ostéoporotique</stong> et en constitue toute la gravité.</p>"},{"i":"f963323cd69f","n":128,"o":"128-1","u":"Définition","t":"Connaître la définition de l’ostéoporose (densitométrique et fractures)","q":"Quelle est la définition générale de l'ostéoporose et quelles sont les composantes de la résistance osseuse ?","a":"<p>L'ostéoporose est une maladie <stong>généralisée et diffuse du squelette</stong> caractérisée par une <stong>résistance osseuse diminuée</stong> prédisposant à un risque élevé de fracture.</p> <p>La résistance osseuse résulte de deux composantes :</p> <ul><li>la <stong>densité osseuse</stong> (liée au contenu minéral osseux)</li><li>la <stong>qualité osseuse</stong> (altération de la microarchitecture osseuse)</li></ul>"},{"i":"942b068d3de3","n":128,"o":"128-10","u":"Contenu multimédia","t":"Radiographie d’ostéoporose avec fracture vertébrale","q":"Quelle est la signification du 'signe du puzzle' dans le cadre d'un tassement vertébral sur une radiographie ?","a":"<p>Le 'signe du puzzle' sur une radiographie, dans le cadre d'un tassement vertébral, indique que la <strong>corticale osseuse reste continue</strong> et peut être suivie sur toute sa longueur, sans interruption. Ce signe est caractéristique d'une <strong>fracture vertébrale ostéoporotique</strong> et permet de l'opposer à une cause maligne où l'on observerait une ostéolyse ou une rupture de la corticale.</p>"},{"i":"e8dc000097a8","n":128,"o":"128-10","u":"Contenu multimédia","t":"Radiographie d’ostéoporose avec fracture vertébrale","q":"Quels sont les signes radiographiques caractéristiques d'une fracture vertébrale ostéoporotique sur une radiographie standard ?","a":"<p>Sur une radiographie standard, les signes d'une fracture vertébrale ostéoporotique sont :</p><ul><li>Une <strong>déminéralisation osseuse homogène</strong> (hypertransparence diffuse).</li><li>Un <strong>tassement</strong> ou une <strong>cunéiformisation</strong> d'un corps vertébral.</li><li>Le <strong>respect du mur postérieur</strong> et des pédicules.</li><li>L'absence de masse des parties molles ou de lyse osseuse.</li></ul>"},{"i":"f4dc28a87dfa","n":128,"o":"128-10","u":"Contenu multimédia","t":"Radiographie d’ostéoporose avec fracture vertébrale","q":"Comment différencier radiographiquement un tassement vertébral ostéoporotique d'un tassement malin ?","a":"<p>Pour différencier radiologiquement un tassement vertébral ostéoporotique d'un tassement malin, il faut rechercher :</p><ul><li>Le <strong>signe du puzzle</strong> (corticale continue sur toute sa longueur, sans ostéolyse) en faveur de l'ostéoporose.</li><li>Le <strong>respect du mur postérieur</strong> et des pédicules (contrairement à une vertèbre borgne maligne).</li><li>L'absence de <strong>masse des parties molles</strong> ou de lyses osseuses associées dans le cas de l'ostéoporose.</li></ul>"},{"i":"0cfbb9d421d2","n":128,"o":"128-12","u":"Définition","t":"Connaître la définition de l’ostéomalacie","q":"Quel est le mécanisme physiopathologique principal de l'ostéomalacie ?","a":"<p>Le mécanisme physiopathologique de l'ostéomalacie est un <strong>retard de minéralisation de la matrice organique (tissu ostéoïde)</strong> nouvellement formée à la surface de l'os.</p>"},{"i":"9088a9c10403","n":128,"o":"128-12","u":"Définition","t":"Connaître la définition de l’ostéomalacie","q":"Quelles sont les causes principales de l'ostéomalacie ?","a":"<p>L'ostéomalacie est principalement causée par des <strong>concentrations insuffisantes en calcium, phosphore et/ou vitamine D</strong>, ces éléments étant essentiels à la minéralisation osseuse.</p>"},{"i":"dd40b06ae1ea","n":128,"o":"128-12","u":"Définition","t":"Connaître la définition de l’ostéomalacie","q":"Quelle est la particularité de l'ostéomalacie chez l'enfant ?","a":"<p>Chez l'enfant, l'ostéomalacie est appelée <strong>rachitisme</strong>. Elle survient lors de périodes de forte croissance et est due à un <strong>déficit sévère en vitamine D et/ou en calcium</strong>.</p>"},{"i":"eddbac90eb3d","n":128,"o":"128-12","u":"Définition","t":"Connaître la définition de l’ostéomalacie","q":"Quelle est la définition de l'ostéomalacie ?","a":"<p>L'ostéomalacie est une <strong>ostéopathie diffuse, raréfiante et fragilisante</strong> du tissu osseux, caractérisée par un <strong>défaut de minéralisation de la matrice osseuse organique</strong> (tissu ostéoïde) nouvellement formée.</p>"},{"i":"35f0b80ae3ca","n":128,"o":"128-13","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques devant faire évoquer le diagnostic d’ostéomalacie","q":"Quelle définition de la carence en vitamine D est utilisée dans le contexte du diagnostic d'ostéomalacie ?","a":"<p>La carence en vitamine D est définie par un taux de <strong>25(OH)-vitamine D inférieur à 10 ng/mL</strong>.</p>"},{"i":"47e5f9f115f8","n":128,"o":"128-13","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques devant faire évoquer le diagnostic d’ostéomalacie","q":"Quels sont les signes cliniques devant faire évoquer le diagnostic d'ostéomalacie ?","a":"<p>Les signes cliniques d'orientation vers une ostéomalacie incluent :</p><ul><li>Une <strong>myopathie proximale</strong> (fréquente, environ 50% des cas), se manifestant par une impotence fonctionnelle sans signe neurologique déficitaire.</li><li>Des <strong>douleurs osseuses</strong> : d'installation insidieuse, de rythme mécanique, avec une topographie initiale pelvi-crurale puis une extension progressive (thoracique, scapulaire, rachidienne, membres), et une aggravation progressive.</li></ul>"},{"i":"e533010fa676","n":128,"o":"128-13","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques devant faire évoquer le diagnostic d’ostéomalacie","q":"Quels sont les arguments biologiques devant faire évoquer le diagnostic d'ostéomalacie par carence en vitamine D ?","a":"<p>Les arguments biologiques majeurs en faveur d'une ostéomalacie par carence en vitamine D sont :</p><ul><li>Une <strong>hypocalcémie</strong>.</li><li>Une <strong>hypocalciurie</strong>.</li><li>Une <strong>hypophosphorémie</strong>.</li><li>Un effondrement du taux de <strong>25(OH)-vitamine D < 5 ng/mL</strong>.</li><li>Une <strong>élévation des phosphatases alcalines</strong> (d'origine osseuse).</li><li>Une <strong>hyperparathyroïdie secondaire</strong>, réactionnelle à l'hypocalcémie.</li></ul>"},{"i":"952bed860b88","n":128,"o":"128-4","u":"Etiologies","t":"Connaître les causes d’ostéoporose primitive et secondaire","q":"Le diabète est-il considéré comme une cause d'ostéoporose secondaire selon le contenu source de l'EDN ?","a":"<p>Non, le contenu source indique que le diabète a été compté <strong>FAUX</strong> comme cause d'ostéoporose secondaire dans une annale, signalant ainsi une discordance à connaître.</p>"},{"i":"99fa78278938","n":128,"o":"128-4","u":"Etiologies","t":"Connaître les causes d’ostéoporose primitive et secondaire","q":"Quelles sont les principales causes endocriniennes d'ostéoporose secondaire et leurs mécanismes osseux spécifiques ?","a":"<p>Les principales causes endocriniennes et leurs mécanismes sont :</p><ul><li><strong>Hypogonadisme</strong> (par diminution des stéroïdes sexuels comme dans l'anorexie, hyperprolactinémie, etc.) : atteint l'<strong>os trabéculaire</strong>.</li><li><strong>Syndrome de Cushing</strong> / <strong>corticothérapie</strong> : diminue la formation et augmente la résorption osseuse, diminue l'absorption et augmente la fuite urinaire du calcium, entraînant une hyperparathyroïdie secondaire. Atteint l'<strong>os trabéculaire</strong> (vertèbres, côtes).</li><li><strong>Hyperthyroïdie</strong> / hormones thyroïdiennes freinatrices : augmente le remodelage en défaveur de la formation osseuse. Atteint l'<strong>os cortical</strong>.</li><li><strong>Hyperparathyroïdie</strong>, hémochromatose : augmente la résorption osseuse. Atteint l'<strong>os cortical</strong>.</li></ul>"},{"i":"9cbb19f408fe","n":128,"o":"128-4","u":"Etiologies","t":"Connaître les causes d’ostéoporose primitive et secondaire","q":"Quelles sont les autres causes d'ostéoporose secondaire, en dehors des atteintes endocriniennes ?","a":"<p>Les autres causes d'ostéoporose secondaire incluent :</p><ul><li><strong>Digestives</strong> : malabsorption (résections, maladie cœliaque), entérocolopathie inflammatoire chronique, cirrhose biliaire primitive, chirurgie bariatrique, gastrectomie.</li><li><strong>Générales</strong> : polyarthrite rhumatoïde, spondylarthrite, lupus érythémateux disséminé, myélome multiple, mastocytose, insuffisance rénale (ostéodystrophie), hémodialyse.</li><li><strong>Génétiques</strong> : ostéogenèse imparfaite, Marfan, Ehler-Danlos, homocystinurie.</li><li><strong>Médicaments</strong> : corticostéroïdes, hormones thyroïdiennes freinatrices, agonistes GnRH, anti-aromatases, anti-convulsivants, anti-calcineurines (ciclosporine, tacrolimus), héparines non fractionnées (HNF), anti-rétroviraux.</li><li>Facteurs de mode de vie : alcool (≥ <strong>3 unités/j</strong>), tabac, carence en <strong>vitamine C</strong>.</li></ul>"},{"i":"aba9ac1e1cfd","n":128,"o":"128-4","u":"Etiologies","t":"Connaître les causes d’ostéoporose primitive et secondaire","q":"Qu'est-ce qu'une ostéoporose primitive et quels en sont les facteurs de risque liés à la densité minérale osseuse (DMO) ?","a":"<p>L'ostéoporose primitive n'a pas de cause secondaire identifiable. Ses facteurs de risque dépendants de la DMO incluent :</p><ul><li>Origine <strong>caucasienne</strong> ou <strong>asiatique</strong>.</li><li>Carence œstrogénique : <strong>ménopause</strong> (surtout <strong>précoce &lt; 40 ans</strong>), nulliparité, aménorrhée.</li><li>Diminution de la sécrétion androgénique.</li><li>Faible apport calcique, carence en <strong>vitamine D</strong> (entraînant une hyperparathyroïdie secondaire).</li><li>Consommation excessive d'<strong>alcool</strong>.</li><li><strong>Corticothérapie</strong> (&gt; <strong>7,5 mg/j</strong> pendant &gt; <strong>3 mois</strong>).</li><li>Faible poids : <strong>IMC &lt; 19</strong>.</li><li>Immobilisation prolongée, tabagisme.</li></ul>"},{"i":"c2b843b0a415","n":128,"o":"128-4","u":"Etiologies","t":"Connaître les causes d’ostéoporose primitive et secondaire","q":"Quels sont les facteurs de risque d'ostéoporose primitive (partiellement) indépendants de la densité minérale osseuse (DMO) ?","a":"<p>Ces facteurs de risque, (partiellement) indépendants de la DMO, prédisposent à l'ostéoporose primitive :</p><ul><li>Âge &gt; <strong>60 ans</strong> (lié au risque de chute, surtout FESF).</li><li>Antécédent familial de <strong>fracture par fragilité</strong> (parent 1er degré).</li><li>Antécédent personnel de <strong>fracture ostéoporotique</strong> (particulièrement si récente).</li><li>Chute ou risque de chute.</li><li>Troubles de l'acuité visuelle, troubles neuromusculaires.</li><li>Endocrinopathies : hyperparathyroïdie, hyperthyroïdie, diabète, Cushing, hypogonadisme.</li><li>Maladies inflammatoires : <strong>polyarthrite rhumatoïde</strong>, BPCO.</li><li>Maladie de Parkinson, carence protéique.</li></ul>"},{"i":"087f8d746185","n":128,"o":"128-5","u":"Diagnostic positif","t":"Connaître les indications de l’ostéodensitométrie et des autres examens d’imagerie","q":"Quelle est la technique de référence pour l'évaluation de l'ostéoporose et quelles sont ses caractéristiques ?","a":"<p>La technique de référence pour l'évaluation de l'ostéoporose est l'<strong>absorptiométrie biphotonique aux rayons X (DXA)</strong>. Elle est caractérisée par une faible irradiation, sa rapidité et sa reproductibilité.</p>"},{"i":"20b0f50a9a50","n":128,"o":"128-5","u":"Diagnostic positif","t":"Connaître les indications de l’ostéodensitométrie et des autres examens d’imagerie","q":"Quels sont les sites de mesure de la DEXA et leurs spécificités dans l'évaluation de l'ostéoporose ?","a":"<ul><li>Le <strong>rachis lombaire</strong>, riche en os trabéculaire, est le site le plus sensible en post-ménopause.</li><li>L'<strong>Extrémité Supérieure du Fémur (ESF)</strong>, plus corticale, est à privilégier après 65-70 ans ou en cas de faux positifs au rachis lombaire (lésions arthrosiques, fractures vertébrales).</li></ul>"},{"i":"272350d254ac","n":128,"o":"128-5","u":"Diagnostic positif","t":"Connaître les indications de l’ostéodensitométrie et des autres examens d’imagerie","q":"Dans quelles situations une deuxième ostéodensitométrie pour suivi est-elle indiquée ?","a":"<p>Une deuxième ostéodensitométrie est indiquée à l'<strong>arrêt d'un traitement anti-ostéoporotique</strong>, ou <strong>3 à 5 ans après un premier examen</strong> normal ou montrant une ostéopénie modérée, en fonction de l'évolution des facteurs de risque.</p>"},{"i":"2873ff64f6ba","n":128,"o":"128-5","u":"Diagnostic positif","t":"Connaître les indications de l’ostéodensitométrie et des autres examens d’imagerie","q":"Quelle est la différence entre le T-score et le Z-score en ostéodensitométrie et à quelles populations s'appliquent-ils ?","a":"<ul><li>Le <strong>T-score</strong> compare la DMO du patient à celle d'un adulte jeune du même sexe. Il est utilisé chez les <strong>femmes et les hommes après 50 ans</strong>. Un T-score ≤ -2,5 définit l'ostéoporose.</li><li>Le <strong>Z-score</strong> compare la DMO du patient à celle de sujets de même âge et sexe. Il est utilisé chez les <strong>femmes non ménopausées, les hommes de moins de 50 ans et les enfants</strong>. Un Z-score &lt; -2 est considéré comme anormal.</li></ul>"},{"i":"7d6b0688c4f8","n":128,"o":"128-5","u":"Diagnostic positif","t":"Connaître les indications de l’ostéodensitométrie et des autres examens d’imagerie","q":"Quelles sont les indications remboursées de l'ostéodensitométrie pour une première évaluation ?","a":"<ul><li>Fracture vertébrale sans contexte traumatique ni tumoral.</li><li>Antécédent de fracture périphérique sans traumatisme majeur (hors crâne, rachis cervical, doigts, orteils).</li><li>Corticoïde thérapie ≥ 7,5 mg/j pendant plus de 3 mois.</li><li>Pathologies inductrices de l'ostéoporose : hyperthyroïdie évolutive, hypercorticisme, hyperparathyroïdie primitive, hypogonadisme, ostéogenèse imparfaite.</li><li>Chez la femme ménopausée, en présence de facteurs de risque additionnels tels qu'un antécédent familial de FESF (1er degré), un IMC &lt; 19, une ménopause précoces (&lt; 40 ans), ou une corticothérapie prolongée.</li></ul>"},{"i":"2d9b3660d22f","n":128,"o":"128-6","u":"Diagnostic positif","t":"Connaître le bilan biologique de 1ère intention","q":"Quels sont les examens biologiques de première intention systématiquement demandés lors d'une suspicion d'ostéopathie fragilisante ?","a":"<p>Les examens biologiques de première intention à réaliser sont :</p><ul><li>Une <strong>NFS</strong> (Numération Formule Sanguine).</li><li>Une <strong>CRP</strong> (C-Réactive Protéine).</li><li>La <strong>créatininémie</strong> avec estimation de la clairance.</li><li>Un bilan hépatique : <strong>ASAT, ALAT, γGT, phosphatases alcalines</strong> (en distinguant les PAL osseuses).</li><li>La <strong>calcémie et la phosphatémie</strong>.</li><li>Le dosage de la <strong>25(OH)-vitamine D</strong> (D2 + D3).</li><li>Une <strong>électrophorèse des protéines sériques</strong> pour rechercher un pic monoclonal (myélome).</li></ul>"},{"i":"babd02e230cb","n":128,"o":"128-6","u":"Diagnostic positif","t":"Connaître le bilan biologique de 1ère intention","q":"Quel est l'objectif du bilan biologique de première intention dans le cadre d'une ostéopathie fragilisante, comme l'ostéoporose commune ?","a":"<p>L'objectif principal du bilan biologique de première intention est :</p><ul><li>D'<strong>éliminer une ostéoporose secondaire</strong>.</li><li>De rechercher un <strong>diagnostic différentiel</strong>.</li></ul><p>Il est important de noter que le bilan est le plus souvent <strong>normal</strong> dans le cas d'une ostéoporose commune et qu'il est inacceptable d'initier un traitement anti-ostéoporotique sans examens biologiques.</p>"},{"i":"6610edbb11c2","n":128,"o":"128-7","u":"Prise en charge","t":"Connaître les différentes mesures hygiéno-diététiques","q":"Quel doit être l'objectif de concentration sérique en vitamine D dans la prise en charge des ostéopathies fragilisantes et quand une supplémentation est-elle nécessaire ?","a":"<p>L'objectif de concentration sérique en vitamine D doit être <strong>≥ 30 ng/mL</strong>. Une supplémentation est nécessaire en cas de <strong>carence</strong>, par exemple selon le protocole de Souberbielle.</p>"},{"i":"b966f2420d2d","n":128,"o":"128-7","u":"Prise en charge","t":"Connaître les différentes mesures hygiéno-diététiques","q":"Quels sont les apports calciques journaliers recommandés dans la prise en charge des ostéopathies fragilisantes, et comment privilégier ces apports ?","a":"<p>Les apports calciques recommandés sont de <strong>1 à 1,2 g/jour</strong> (à évaluer par un questionnaire). Il est préférable de privilégier les apports naturels :</p><ul><li><strong>Au moins 1 produit laitier par repas</strong>.</li><li>Consommation d'<strong>eaux fortement minéralisées</strong> (ex: Contrex®, Hépar®, Courmayeur®).</li></ul><p>Le calcium per os est souvent mal toléré (nausées, constipation) ce qui peut entraîner une mauvaise observance.</p>"},{"i":"d9df1a069d42","n":128,"o":"128-7","u":"Prise en charge","t":"Connaître les différentes mesures hygiéno-diététiques","q":"Quelles sont les principales mesures hygiéno-diététiques relevant du mode de vie à conseiller dans le cadre de la prise en charge des ostéopathies fragilisantes ?","a":"<p>Les principales mesures hygiéno-diététiques relevant du mode de vie sont :</p><ul><li>La pratique d'une <strong>activité physique régulière « en charge »</strong> pour préserver le capital osseux.</li><li>L'<strong>arrêt du tabac et de l'alcool</strong>.</li><li>La <strong>prévention des chutes</strong>. L'utilisation de protecteurs de hanche a une efficacité limitée par l'observance.</li></ul>"}]};